ZO_CreateStringId("DE_SETTINGS_PANEL_DESC", "Tracks configured dynamic encounters in Stonefalls, Glenumbra, and Auridon: current step, participation, chest timing, and an estimated respawn window. Encounter names and step text come directly from ESO and are displayed in your game language.")
ZO_CreateStringId("DE_SETTINGS_SECTION_STATUS_CONTENT_DESC", "Determines what is displayed in the status window during a tracked encounter, and in which scenes the window appears at all.")
ZO_CreateStringId("DE_SETTINGS_SECTION_STATUS_STYLE_DESC", "Size, colors and background of the status window. These settings do not change what information is displayed.")
ZO_CreateStringId("DE_SETTINGS_SECTION_CHEST_DESC", "A notification appears only for chest timings that have an explicit, tested rule for the current encounter. Chest timing is not inferred generally from step progress.")
ZO_CreateStringId("DE_SETTINGS_SECTION_RESET_DESC", "Reset only affects window position and appearance. It does not change what information is displayed and does not affect the respawn timer overrides below.")
ZO_CreateStringId("DE_SETTINGS_STATUS_SHOW", "Show status window")
ZO_CreateStringId("DE_SETTINGS_STATUS_MOVABLE", "Status window movable")
ZO_CreateStringId("DE_SETTINGS_STATUS_MOVABLE_TT", "Allows moving and changing the window width. When locked, the status window does not respond to the mouse.")
ZO_CreateStringId("DE_SETTINGS_MINIMAL_MODE", "Minimal mode")
ZO_CreateStringId("DE_SETTINGS_MINIMAL_MODE_TT", "Shows only a compact status line without zone, encounter name, and section. Can also be toggled with the small button in the top-right corner of the status window.")
ZO_CreateStringId("DE_SETTINGS_SHOW_CLOSE_BUTTON", "Show close button")
ZO_CreateStringId("DE_SETTINGS_SHOW_CLOSE_BUTTON_TT", "Shows the X button in the top-right corner of the status window for closing it. If hidden, the window can still be shown or hidden via \"Show status window\".")
ZO_CreateStringId("DE_SETTINGS_SHOW_MINIMAL_TOGGLE_BUTTON", "Show minimal mode button")
ZO_CreateStringId("DE_SETTINGS_SHOW_MINIMAL_TOGGLE_BUTTON_TT", "Shows the small button in the top-right corner of the status window for toggling minimal mode. If hidden, minimal mode remains usable via the \"Minimal mode\" setting.")
ZO_CreateStringId("DE_SETTINGS_HIDE_MENUS", "Hide in menus")
ZO_CreateStringId("DE_SETTINGS_HIDE_MENUS_TT", "Hides the status window in the inventory, character menu, crafting and settings, among other things.")
ZO_CreateStringId("DE_SETTINGS_WORLD_MAP", "View on the world map")
ZO_CreateStringId("DE_SETTINGS_WORLD_MAP_TT", "Also shows the status window on the world map. This setting applies regardless of the general menu hiding.")
ZO_CreateStringId("DE_SETTINGS_SHOW_STEP", "Show step number in status")
ZO_CreateStringId("DE_SETTINGS_SHOW_STEP_TT", "Adds “Step x/y” to the status during an ongoing encounter. If a position cannot yet be clearly determined, “?/y” appears.")
ZO_CreateStringId("DE_SETTINGS_SHOW_STEP_PROGRESS", "Show step progress in status")
ZO_CreateStringId("DE_SETTINGS_SHOW_STEP_PROGRESS_TT", "Adds the percentage of the current API target to the status. If no numeric value is available, a dash appears.")
ZO_CreateStringId("DE_SETTINGS_SHOW_PARTICIPATION", "Show participation status")
ZO_CreateStringId("DE_SETTINGS_SHOW_PARTICIPATION_TT", "Adds “Participation detected”, “Participation open”, or “Participation unknown” to the status line. Detected participation remains saved for the current encounter.")
ZO_CreateStringId("DE_SETTINGS_SHOW_SECTION", "Show current section")
ZO_CreateStringId("DE_SETTINGS_SHOW_SECTION_TT", "Shows the localized section text of the currently recognized event step. Long texts are wrapped to fit the window width and automatically increase the window height.")
ZO_CreateStringId("DE_SETTINGS_SHOW_HINT", "Show notification line in status window")
ZO_CreateStringId("DE_SETTINGS_SHOW_HINT_TT", "Shows additional localized ESO hints and active chest notifications. Long text wraps to fit the window width.")
